module coprime_counter(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] a,\n    input wire [3:0] b,\n    input wire [3:0] c,\n    input wire [3:0] d,\n    output wire [15:0] result,\n    output wire done\n);\n    reg [3:0] x_reg, y_reg;\n    reg [15:0] count_reg;\n    reg done_reg;\n    reg [2:0] state;\n\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COMPUTE_GCD = 3'd1;\n    localparam [2:0] CHECK_GCD = 3'd2;\n    localparam [2:0] INCR_Y = 3'd3;\n    localparam [2:0] INCR_X = 3'd4;\n    localparam [2:0] DONE_STATE = 3'd5;\n\n    function automatic [3:0] gcd;\n        input [3:0] a;\n        input [3:0] b;\n        reg [3:0] x, y, temp;\n        begin\n            x = a;\n            y = b;\n            if (y != 0) begin\n                temp = y;\n                y = x % y;\n                x = temp;\n            end\n            if (y != 0) begin\n                temp = y;\n                y = x % y;\n                x = temp;\n            end\n            if (y != 0) begin\n                temp = y;\n                y = x % y;\n                x = temp;\n            end\n            if (y != 0) begin\n                temp = y;\n                y = x % y;\n                x = temp;\n            end\n            if (y != 0) begin\n                temp = y;\n                y = x % y;\n                x = temp;\n            end\n            if (y != 0) begin\n                temp = y;\n                y = x % y;\n                x = temp;\n            end\n            gcd = x;\n        end\n    endfunction\n\n    wire [3:0] current_gcd = gcd(x_reg, y_reg);\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            x_reg <= 4'd0;\n            y_reg <= 4'd0;\n            count_reg <= 16'd0;\n            done_reg <= 1'b0;\n            state <= IDLE;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done_reg <= 1'b0;\n                    if (start) begin\n                        x_reg <= a;\n                        y_reg <= c;\n                        count_reg <= 16'd0;\n                        state <= COMPUTE_GCD;\n                    end\n                end\n\n                COMPUTE_GCD: state <= CHECK_GCD;\n\n                CHECK_GCD: begin\n                    if (current_gcd == 4'd1) begin\n                        count_reg <= count_reg + 16'd1;\n                    end\n                    state <= INCR_Y;\n                end\n\n                INCR_Y: begin\n                    if (y_reg < d) begin\n                        y_reg <= y_reg + 4'd1;\n                        state <= COMPUTE_GCD;\n                    end else begin\n                        y_reg <= c;\n                        state <= INCR_X;\n                    end\n                end\n\n                INCR_X: begin\n                    if (x_reg < b) begin\n                        x_reg <= x_reg + 4'd1;\n                        state <= COMPUTE_GCD;\n                    end else begin\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done_reg <= 1'b1;\n                    if (!start) state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    assign result = count_reg;\n    assign done = done_reg;\nendmodule